      "path": "engine/aggregation/build_canonical.py",
      "content": "#!/usr/bin/env python3\n\"\"\"build_canonical.py — 统一聚合器：全部数据源 → generated/current/canonical.json。\n\nP1 数据层收敛：原先埋在 scripts/gen_plugins_all.py main() 的数据半场（快照装载 /\ncanonical 归并 / 定位复核 / 登记兜底 / 改名跟随 / desc 回填重分类 / 统计）整体上移至此，\n渲染半场在 engine/rendering/render_all.py，导出半场在 scripts/export-data.py——\n三者共享 canonical.json 这一个事实源，Markdown 不再被反向解析。\n\n快照装载（ADR-0002 落地）：基线 ⊕ 30 天窗口。data/snapshot-baseline.json 承载窗口外\n全部历史轮的 (name,url) 合并条目与轮次元信息；无基线文件时自动回退全量扫描（与旧管线\n行为一致，保证基线生成前后产物逐字节等价）。装载 IO 从 567 文件降为窗口数。\n\n验收铁律：canonical ⊕ render_all 的 PLUGINS-ALL.md / catalog/all/*.md 与旧管线逐字节\n一致；export-data 从 canonical 直出的 latest.json / plugins-all.json 与旧正则解析\n逐字段一致（generated_at 除外）。\n\"\"\"\nimport glob\nimport json\nimport re\nimport sys\nfrom collections import Counter\nfrom datetime import datetime, timedelta, timezone\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'lib'))\nfrom radar.atomicio import atomic_write_json  # noqa: E402\nfrom radar.sanitize import sanitize_desc, sanitize_name, url_guard  # noqa: E402\nfrom radar.repository_identity import RepositoryIdentities, dedupe_public_rows  # noqa: E402\n\nROOT = Path(__file__).resolve().parent.parent.parent\nSNAP_DIR = ROOT / 'data' / 'snapshots'\nBASELINE = ROOT / 'data' / 'snapshot-baseline.json'\nLOCATE_CACHE = ROOT / 'data' / 'locate-cache.json'\nDESC_CACHE = ROOT / 'data' / 'desc-cache.json'\nREPO_MAP = ROOT / 'data' / 'repo-map.json'\nURL_AUDIT = ROOT / 'data' / 'url-audit.json'\nOUT = ROOT / 'generated' / 'current' / 'canonical.json'\nWINDOW_DAYS = 30\n\nREAL_URL_RE = re.compile(r'github\\.com/([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+)')\nCONFLICTING_VERDICTS = ('✅ 运行级可用', '❌ 运行级不兼容')\n\nsys.path.insert(0, str(ROOT / 'scripts'))\nfrom classify import classify  # noqa: E402\n\n\ndef bj(iso):\n    \"\"\"ISO 时间串 → 北京时间（UTC+8）；带时区偏移的输入按原偏移换算，避免二次加 8。\"\"\"\n    dt = datetime.fromisoformat(str(iso).replace('Z', '+00:00'))\n    if dt.tzinfo is None:\n        dt = dt.replace(tzinfo=timezone.utc)\n    return dt.astimezone(timezone(timedelta(hours=8))).strftime('%Y-%m-%d %H:%M') + ' UTC+8'\n\n\ndef _read_json_safe(p, default):\n    \"\"\"缓存文件损坏（截断/无效 UTF-8/坏 JSON）时降级返回默认值，不阻断清单生成。\"\"\"\n    try:\n        return json.loads(Path(p).read_text())\n    except (json.JSONDecodeError, UnicodeDecodeError, OSError):\n        return default\n\n\n# 平台基座仓（policy.platform_repositories）：harness 本体非插件，装进 profile\n# 当插件测必然失败——判定无意义且污染 incompatible 统计，目录与统计一并排除。\nPOLICY = _read_json_safe(ROOT / 'catalog' / 'policy.json', {})\nPLATFORM_REPOS = {str(k).strip().lower() for k in (POLICY.get('platform_repositories') or {})}\n\n\ndef _merge_snapshot_files(files, merged, rounds):\n    \"\"\"files 须为新→旧序；(name,url) 同键以最新轮覆盖（setdefault），返回读取的文件数。\"\"\"\n    n = 0\n    for fp in files:\n        try:\n            d = json.loads(Path(fp).read_text())\n        except (json.JSONDecodeError, UnicodeDecodeError, OSError):\n            continue   # 单文件截断/损坏跳过（镜像仓实测案例），不阻断清单生成\n        if not str(d.get('schema', '')).startswith('radar-snapshot/'):\n            continue\n        n += 1\n        rounds.append((d['run_id'], d.get('generated_at', '')))\n        for e in d.get('catalog_entries') or []:\n            merged.setdefault((e['name'], e.get('url', '')), dict(e))\n    return n\n\n\ndef load_entries():\n    \"\"\"全部数据装载：现存快照全扫（新→旧）⊕ 基线补被裁历史。\n\n    裁剪（rebaseline --prune）把 IO 边界交给磁盘：窗口外文件删除、其信息并入\n    data/snapshot-baseline.json；本函数读现存全部文件 + 基线条目垫底（setdefault，\n    现存总是更新）、基线轮次去重后续接（基线轮次恒旧于现存滞留文件）。\n    无基线文件时退化为旧 load_snapshots() 全量行为（逐字节一致）。\n\n    返回 (合并条目列表[保持旧管线遭遇序], [轮次(run_id, generated_at)], 读取文件数)。\n    \"\"\"\n    files = sorted(glob.glob(str(SNAP_DIR / '*.json')), reverse=True)\n    merged, rounds = {}, []\n    n = _merge_snapshot_files(files, merged, rounds)\n    if BASELINE.is_file():\n        base = _read_json_safe(BASELINE, {}) or {}\n        seen_rids = {rid for rid, _ in rounds}\n        rounds += [tuple(r) for r in base.get('rounds', []) if r[0] not in seen_rids]\n        for e in base.get('entries', []):\n            merged.setdefault((e['name'], e.get('url', '')), dict(e))\n    return list(merged.values()), rounds, n\n\n\ndef canonical_key(e, repo_map, locate, identities=None):\n    \"\"\"条目 → 规范主键。真实 URL > repo-map local_key > locate-cache；均无则退回原始键。\"\"\"\n    url = e.get('url') or ''\n    if 'search?q=' not in url:\n        m = REAL_URL_RE.search(url)\n        if m:\n            full = f\"{m.group(1)}/{m.group(2)}\"\n            return ('repo', (identities.resolve(full) if identities else full).lower())\n    name = e['name']\n    r = repo_map.get(name)\n    if r and r.get('full_name'):\n        full = r['full_name']\n        return ('repo', (identities.resolve(full) if identities else full).lower())\n    lc = locate.get(name) or {}\n    if lc.get('status') == 'found' and lc.get('full_name'):\n        full = lc['full_name']\n        return ('repo', (identities.resolve(full) if identities else full).lower())\n    return ('raw', name.lower(), url)\n\n\ndef _ok_desc(d):\n    d = (d or '').strip()\n    return bool(d) and d != '—' and not d.startswith('http')\n\n\ndef merge_entry(a, b):\n    \"\"\"同 canonical 的更旧轮次 b 补齐/仲裁 a：URL 取真实、star 取大、desc 取有效、判定冲突降待定。\"\"\"\n    out = dict(a)\n    if 'search?q=' in (out.get('url') or '') and 'search?q=' not in (b.get('url') or ''):\n        out['url'] = b['url']\n    if (out.get('star') or 0) < (b.get('star') or 0):\n        out['star'] = b['star']\n    if not out.get('bundle') and b.get('bundle'):\n        out['bundle'] = b['bundle']\n    if not _ok_desc(out.get('desc')) and _ok_desc(b.get('desc')):\n        out['desc'] = b['desc']\n    if not out.get('domain') and b.get('domain'):\n        out['domain'] = b['domain']\n    va, vb = out.get('verdict'), b.get('verdict')\n    if out.get('verdict_conflict') or b.get('verdict_conflict'):\n        out['verdict'] = '⚠️ 待定'\n        out['verdict_conflict'] = out.get('verdict_conflict') or b['verdict_conflict']\n    elif va != vb:\n        if vb in CONFLICTING_VERDICTS and va not in CONFLICTING_VERDICTS:\n            out['verdict'] = vb\n        elif va in CONFLICTING_VERDICTS and vb not in CONFLICTING_VERDICTS:\n            pass\n        elif va in CONFLICTING_VERDICTS and vb in CONFLICTING_VERDICTS:\n            out['verdict'] = '⚠️ 待定'\n            out['verdict_conflict'] = f'{va} ↔ {vb}'\n    return out\n\n\ndef canonical_merge(entries, repo_map, locate, identities=None):\n    \"\"\"按 canonical 主键归并（装载产出的条目序近似新→旧）。返回 (归并条目, 统计)。\"\"\"\n    groups, order, plain = {}, [], {}\n    for e in entries:\n        e = dict(e)\n        if identities and url_guard(e.get('url') or ''):\n            full = e['url'].split('github.com/')[1].strip('/')\n            current = identities.resolve(full)\n            if full.lower() != current.lower():\n                if e['name'].lower() in {full.split('/')[-1].lower(), full.lower().replace('/', '-')}:\n                    e['name'] = current.split('/')[-1]\n                e['url'] = f'https://github.com/{current}'\n        k = canonical_key(e, repo_map, locate, identities)\n        if k not in groups:\n            groups[k] = dict(e)\n            order.append(k)\n        else:\n            groups[k] = merge_entry(groups[k], e)\n        if k[0] == 'repo':\n            repo_part = k[1].split('/')[1]\n            if e['name'].lower() == repo_part:\n                plain.setdefault(k, e['name'])\n    final = []\n    for k in order:\n        g = groups[k]\n        if k in plain:\n            g['name'] = plain[k]\n        final.append(g)\n    n_dedup = len(entries) - len(final)\n    n_conflict = sum(1 for g in final if g.get('verdict_conflict'))\n    return final, (n_dedup, n_conflict)\n\n\ndef pr_registered_names():\n    names = set()\n    for fp in glob.glob(str(ROOT / 'catalog' / 'plugins' / '*.json')):\n        d = _read_json_safe(fp, None)\n        if not isinstance(d, dict):\n            continue\n        full = d.get('repository', {}).get('full_name', '')\n        if full:\n            names.add(full.split('/')[-1])\n    return names\n\n\ndef vc_local(entries, dom, verdict):\n    return sum(1 for e in entries if e.get('domain') == dom and e.get('locate') == 'located'\n               and e.get('verdict') == verdict)\n\n\nDOMAIN_ORDER = ['🎓 技能包', '🧠 记忆增强', '🎨 主题皮肤', '🛒 市场与管理',\n                '🔌 Web UI 增强', '💻 编码开发', '🤖 Agent 能力', '📡 消息通讯',\n                '🗂 文件数据', '🎮 娱乐生活', '🛠 基建部署', '📚 学习研究', '❓ 其他']\n\n# 导出契约映射（与 scripts/export-data.py 的 VERDICT_MAP/MARK 同源；标注见该文件）\nEXPORT_VERDICT = {'✅ 运行级可用': 'ok', '❌ 运行级不兼容': 'incompatible',\n                  '⚠️ 待定': 'pending', '⏳ 未测': 'untested'}\n\n\ndef build(root: Path = ROOT):\n    \"\"\"执行全部数据阶段，写 generated/current/canonical.json 并返回 canonical 文档。\"\"\"\n    entries, rounds, n_files = load_entries()\n    locate = (_read_json_safe(LOCATE_CACHE, {}) or {}).get('entries', {}) if LOCATE_CACHE.exists() else {}\n    repo_map = (_read_json_safe(REPO_MAP, {}) or {}).get('entries', {}) if REPO_MAP.exists() else {}\n    desc_cache = _read_json_safe(DESC_CACHE, {}) if DESC_CACHE.exists() else {}\n    url_audit = (_read_json_safe(URL_AUDIT, {}) or {}).get('entries', {}) if URL_AUDIT.exists() else {}\n    pr_names = pr_registered_names()\n    identities = RepositoryIdentities.load(root)\n\n    entries, (n_dedup, n_conflict) = canonical_merge(entries, repo_map, locate, identities)\n\n    # 实时 star 映射（locate-cache 的 full_name → stargazerCount），对全部已定位条目生效\n    live_star = {identities.resolve(r['full_name']).lower(): r['star'] for r in locate.values()\n                 if r.get('status') == 'found' and r.get('full_name') and isinstance(r.get('star'), int)}\n\n    # 日更 GQL 星缓存（refresh-stars bot 回流 data/star-cache.json）最高优先：\n    # locate 星为定位时快照会陈旧（2026-10-02 全量低报根因），star-cache 每日全量刷新。\n    _sc = (_read_json_safe(ROOT / 'data' / 'star-cache.json', {}) or {}).get('entries') or {}\n    _n_sc = 0\n    for _k, _v in _sc.items():\n        if isinstance(_v, dict) and isinstance(_v.get('star'), int):\n            live_star[identities.resolve(_k).lower()] = _v['star']\n            _n_sc += 1\n    if _n_sc:\n        print(f'[canonical] star-cache 覆盖 {_n_sc} 条实时星')\n\n    n_fix = n_empty = n_amb = n_unresolved = n_star = 0\n    for e in entries:\n        if 'search?q=' in (e.get('url') or ''):\n            r = locate.get(e['name'], {})\n            if r.get('status') == 'found':\n                e['url'] = f\"https://github.com/{identities.resolve(r['full_name'])}\"\n                e['locate'] = 'located'\n                n_fix += 1\n            elif r.get('status') == 'not_found':\n                e['locate'] = 'empty_watch'\n                n_empty += 1\n            elif r.get('status'):\n                e['locate'] = 'ambiguous_watch'\n                n_amb += 1\n            else:\n                e['locate'] = 'unresolved'   # 新占位且无复核缓存\n                n_unresolved += 1\n        else:\n            e['locate'] = 'located'\n        # 消亡仓库降级（url-audit 判 gone：已删除/改名/转私有 → 空仓监测，不呈现链接）\n        m0 = REAL_URL_RE.search(e.get('url') or '')\n        if e['locate'] == 'located' and m0 \\\n                and url_audit.get(f\"{m0.group(1)}/{m0.group(2)}\".lower(), {}).get('status') == 'gone':\n            e['locate'] = 'empty_watch'\n            n_empty += 1\n        # 实时 star 覆盖（含真实 URL 条目与合并条目；快照层 star 陈旧或为 0）\n        m = REAL_URL_RE.search(e.get('url') or '')\n        if m:\n            ls = live_star.get(f\"{m.group(1)}/{m.group(2)}\".lower())\n            if ls is not None:\n                e['star'] = ls\n                n_star += 1\n\n    # 登记表兜底（#189）：PLUGINS.md 表行有、已定位集合没有的仓，按登记信息补行\n    n_floor = n_floor_gone = 0\n    reg_md = ROOT / 'PLUGINS.md'\n    if reg_md.is_file():\n        have = set()\n        for e in entries:\n            mh = REAL_URL_RE.search(e.get('url') or '')\n            if mh:\n                have.add(f\"{mh.group(1)}/{mh.group(2)}\".lower())\n            have.add(e['name'].lower().replace('/', '-'))\n        for line in reg_md.read_text().splitlines():\n            rm = re.match(r'^\\|\\s*([^|]+?)\\s*\\|\\s*\\[[^\\]]*\\]\\('\n                          r'(https://github\\.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+?)/?\\)\\s*\\|\\s*([^|]*)', line)\n            if not rm:\n                continue\n            name, url, desc = rm.group(1).strip(), rm.group(2), rm.group(3).strip()\n            full = identities.resolve(url.split('github.com/')[1].strip('/')).lower()\n            if full in have:\n                continue\n            dom, _hit = classify(name, desc)\n            fe = {'name': name or full.split('/')[1], 'url': f\"https://github.com/{full}\",\n                  'star': live_star.get(full), 'verdict': '⏳ 未测',\n                  'domain': dom, 'desc': desc or '—', 'locate': 'located'}\n            if url_audit.get(full, {}).get('status') == 'gone':\n                fe['locate'] = 'empty_watch'\n                n_floor_gone += 1\n            else:\n                n_floor += 1\n            entries.append(fe)\n            have.add(full)\n\n    # canonical 改名跟随（repo-map aliases → 引擎登记的最新全名；名称文本仅在等于旧仓名时改写）\n    rm_canon = identities.aliases\n    n_rename = 0\n    for e in entries:\n        if e.get('locate') != 'located':\n            continue\n        m1 = REAL_URL_RE.search(e.get('url') or '')\n        if not m1:\n            continue\n        cur = f\"{m1.group(1)}/{m1.group(2)}\".lower()\n        canon = rm_canon.get(cur)\n        if not canon or canon.lower() == cur:\n            continue\n        if e['name'].lower() == cur.split('/')[1]:\n            e['name'] = canon.split('/')[1]\n        e['url'] = f\"https://github.com/{canon}\"\n        n_rename += 1\n\n    # 定位修复与登记兜底会使不同原键收敛为同仓；目录/统计之前再次归并，而非只在导出处去重。\n    entries, (n_post_dedup, _) = canonical_merge(entries, repo_map, locate, identities)\n    n_dedup += n_post_dedup\n    n_conflict = sum(1 for e in entries if e.get('verdict_conflict'))\n\n    # desc 回填（GitHub 描述缓存）+「其他」兜底重分类（taxonomy v2 规则，仅动其他类）\n    n_desc = n_reclass = 0\n    for e in entries:\n        desc = (e.get('desc') or '').strip()\n        if (not desc or desc == '—' or desc.startswith('http')) and e.get('locate') == 'located':\n            full = e['url'].split('github.com/')[1].strip('/') if 'github.com/' in e.get('url', '') else ''\n            if full.count('/') == 1 and desc_cache.get(full):\n                e['desc'] = desc_cache[full]\n                n_desc += 1\n        if e.get('domain') == '❓ 其他':\n            dom, _hit = classify(e['name'], e.get('desc') or '')\n            if dom != '❓ 其他':\n                e['domain'] = dom\n                e['reclassed'] = True\n                n_reclass += 1\n\n    # ── 内容消毒（P2b，单一收口：render_all 与 export-data 同源消费）──────────\n    # 换行/回车 → 空格（杀条目伪造）；desc 方括号转义（杀钓鱼链接注入）；\n    # 真实 URL 过 GitHub 白名单，不过则降级为无链接条目。\n    # 实测当前数据：name 零命中、URL 零违规（零漂移）；desc 方括号 16 条（有意变更）。\n    n_sanitized = 0\n    for e in entries:\n        s_name = sanitize_name(e.get('name') or '')\n        s_desc = sanitize_desc(e.get('desc') or '')\n        if s_name != e.get('name') or s_desc != e.get('desc'):\n            n_sanitized += 1\n        e['name'], e['desc'] = s_name, s_desc\n        u = e.get('url') or ''\n        if 'search?q=' not in u and url_guard(u) is None:\n            # 白名单外降级到歧义监测轨道：无链接、判定不展示（可见降级，非静默丢弃；\n            # 复用既有渲染路径，不引入\"空 URL 假链接\"这类不变量破坏）\n            e['locate'] = 'ambiguous_watch'\n            n_sanitized += 1\n\n    # ── 平台基座仓排除：单点过滤，统计/导出/目录全部下游一致生效 ──────────────\n    if PLATFORM_REPOS:\n        _name_set = {p.replace('/', '-') for p in PLATFORM_REPOS}\n        _before = len(entries)\n        entries = [e for e in entries\n                   if (e.get('url') or '').split('github.com/')[-1].strip('/').lower() not in PLATFORM_REPOS\n                   and e.get('name', '').lower().replace('/', '-') not in _name_set]\n        n_platform = _before - len(entries)\n        if n_platform:\n            print(f'[canonical] platform repos excluded: {n_platform} ({sorted(PLATFORM_REPOS)})')\n\n    # 统计在全部消毒/降级完成后计算（外审 P1：曾先算后消毒，URL 降级后\n    # stats_located/export_stats 保留旧定位状态——当前数据零违规零漂移，逻辑修正）\n    n_empty = sum(e['locate'] == 'empty_watch' for e in entries)\n    n_amb = sum(e['locate'] == 'ambiguous_watch' for e in entries)\n    n_unresolved = sum(e['locate'] == 'unresolved' for e in entries)\n    vc = Counter(e['verdict'] for e in entries if e['locate'] == 'located')\n    v_all = Counter(e['verdict'] for e in entries)\n\n    # ── 导出直出数据（供 export-data 消费，免 Markdown 反解析）─────────────────\n    # 顺序契约 = 旧管线 catalog/all/*.md 按文件名字典序拼接 × 组内 (❌沉尾, star 降序)；\n    # 只含 locate=located 条目（旧正则只匹配带真实链接的行）。\n    export_rows = []\n    for dom in sorted(DOMAIN_ORDER, key=lambda d: f\"{d.split(' ', 1)[-1]}.md\"):\n        group = sorted([e for e in entries if e.get('domain') == dom],\n                       key=lambda x: (x.get('verdict') == '❌ 运行级不兼容', -(x.get('star') or 0)))\n        for e in group:\n            if e.get('locate') != 'located':\n                continue\n            desc = (e.get('desc') or '—').strip()\n            if desc.startswith('http'):\n                desc = '—'\n            pr = ' 〔PR〕' if e['name'] in pr_names else ''\n            bundle = '〔📦〕' if e.get('bundle') else ''\n            export_rows.append({\n                'repo': e['url'].split('github.com/')[1],\n                'name': e['name'],\n                'verdict': EXPORT_VERDICT.get(e.get('verdict'), 'untested'),\n                'stars': e.get('star') if isinstance(e.get('star'), int) else None,\n                'desc': f'{desc}{pr}{bundle}',\n            })\n    # 出口再验证归一身份；与站点和历史 Markdown 导出共享同仓标签/星数/判定归并规则。\n    export_rows = dedupe_public_rows(export_rows, identities)\n\n    # 四档清单统计在同仓去重与判定仲裁后按最终 rows 计数，与对外数组逐条一致\n    # （曾用去重前的 vc，latest.stats 与 plugins[] 实际计数漂移——语义门禁校验的就是它）；\n    # 监测三态（gone/ambiguous/unlocated）不进入 rows，单独计数，不能与 total_listed 相加对账。\n    row_counts = Counter(p['verdict'] for p in export_rows)\n    export_stats = {\n        'ok': row_counts.get('ok', 0),\n        'incompatible': row_counts.get('incompatible', 0),\n        'pending': row_counts.get('pending', 0),\n        'untested': row_counts.get('untested', 0),\n        'gone': n_empty,\n        'ambiguous': n_amb,\n        'unlocated': n_unresolved,\n    }\n\n    doc = {\n        'schema': 'radar-canonical/v1',\n        'generated_at': datetime.now(timezone.utc).isoformat(timespec='seconds'),\n        'loader': {'files_read': n_files, 'window_days': WINDOW_DAYS,\n                   'baseline_used': bool(BASELINE.is_file())},\n        'rounds': rounds,\n        'snapshot_run_id': rounds[0][0] if rounds else None,\n        'entries': entries,\n        'counts': {'total': len(entries), 'dedup': n_dedup, 'conflict': n_conflict,\n                   'locate_fixed': n_fix, 'empty_watch': n_empty, 'ambiguous_watch': n_amb,\n                   'unresolved': n_unresolved, 'live_star': n_star,\n                   'floor_added': n_floor, 'floor_gone': n_floor_gone,\n                   'rename_followed': n_rename, 'desc_backfilled': n_desc, 'reclassed': n_reclass,\n                   'pr_registered': len(pr_names)},\n        'stats_located': dict(vc), 'stats_all': dict(v_all), 'pr_names': sorted(pr_names),\n        'domain_stats': {dom: {'total': sum(1 for e in entries if e.get('domain') == dom),\n                               'ok': vc_local(entries, dom, '✅ 运行级可用'),\n                               'bad': vc_local(entries, dom, '❌ 运行级不兼容'),\n                               'inc': vc_local(entries, dom, '⚠️ 待定'),\n                               'un': vc_local(entries, dom, '⏳ 未测'),\n                               'watch': sum(1 for e in entries if e.get('domain') == dom\n                                            and e.get('locate') != 'located')}\n                         for dom in DOMAIN_ORDER},\n        'global': {'un': vc.get('⏳ 未测', 0), 'located': sum(vc.values()), 'all': len(entries)},\n        'export': {'rows': export_rows, 'stats': export_stats,\n                   'anchor_run_id': rounds[0][0] if rounds else None},\n    }\n    atomic_write_json(OUT, doc)\n    print(f'[build-canonical] {len(entries)} 条（去重 {n_dedup} · 冲突 {n_conflict} · 定位修复 {n_fix} · '\n          f'空仓 {n_empty} · 歧义 {n_amb} · 未定位 {n_unresolved} · 实时星 {n_star}）'\n          f'→ {OUT.relative_to(ROOT)}（快照读取 {n_files} 文件）')\n    return doc\n\n\ndef main() -> int:\n    build()\n    return 0\n\n\nif __name__ == '__main__':\n    sys.exit(main())\n"
    },
    {
      "path": "engine/rendering/render_all.py",
      "content": "#!/usr/bin/env python3\n\"\"\"render_all.py — 渲染半场：canonical.json → PLUGINS-ALL.md + catalog/all/*.md。\n\nP1 数据层收敛：原 scripts/gen_plugins_all.py main() 的 Markdown 半场上移至此，\n唯一输入为 engine/aggregation/build_canonical.py 产出的 canonical 文档\n（dict 或 generated/current/canonical.json），不再自读快照/缓存——渲染与导出\n同源，Markdown 从此是纯消费端。\n\n副作用保留：tile_assets 磁贴生成（runner-smoke 冒烟断言依赖）。\n返回值契约不变：{'domains': {...}, 'global': {...}}（render-readme-from-snapshot.py 消费）。\n\"\"\"\nimport json\nimport re\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'aggregation'))\nsys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'scripts'))\nfrom build_canonical import DOMAIN_ORDER, bj, vc_local  # noqa: E402\n\nROOT = Path(__file__).resolve().parent.parent.parent\nCANON = ROOT / 'generated' / 'current' / 'canonical.json'\nOUT = ROOT / 'PLUGINS-ALL.md'\n\nMARK = {'✅ 运行级可用': '🟩 `[可用]`', '❌ 运行级不兼容': '🟨 `[不兼容]`',\n        '⚠️ 待定': '⬜ `[待定]`', '⏳ 未测': '⬜ `[未测]`'}\n\n\ndef _version_key(t):\n    m = re.match(r'(\\d+)\\.(\\d+)\\.(\\d+)-rc\\.(\\d+)$', t)\n    return (int(m.group(1)), int(m.group(2)), int(m.group(3)), int(m.group(4))) if m else (0, 0, 0, 0)\n\n\ndef _runner_version_line(radar_ver):\n    \"\"\"测试版本累计行：runner-versions.json 多版本分解；缺文件时回退磁贴版本串。\"\"\"\n    try:\n        rv = json.loads((ROOT / 'data' / 'runner-versions.json').read_text())\n        latest = rv.get('latest', radar_ver)   # 键缺失才回退磁贴版本——与旧口径逐字一致\n        vd = ' · '.join(f\"{t}（{sum(c.values())}）\" for t, c in\n                        sorted(rv.get('versions', {}).items(),\n                               key=lambda kv: (kv[0] == latest, _version_key(kv[0])), reverse=True))\n        return f\"- 测试版本（多主线累计）：{vd}；最新 `{latest}`（烤入磁贴右段）\"\n    except Exception:\n        return f\"- 测试版本（多主线累计）：{radar_ver}；最新 `{radar_ver}`（烤入磁贴右段）\"\n\n\ndef render(canonical=None) -> dict:\n    if canonical is None:\n        canonical = json.loads(CANON.read_text(encoding='utf8'))\n    entries = canonical['entries']\n    counts = canonical['counts']\n    vc = canonical['stats_located']\n    v_all = canonical['stats_all']\n    pr_names = set(canonical.get('pr_names') or [])\n    n_empty, n_amb = counts['empty_watch'], counts['ambiguous_watch']\n    n_unresolved, n_fix = counts['unresolved'], counts['locate_fixed']\n\n    radar_ver = ''\n    try:\n        import tile_assets\n        tile_assets.write_tiles()\n        radar_ver = tile_assets.current_version()\n    except Exception:\n        pass\n\n    rounds = canonical.get('rounds') or []\n    src = ' ⊕ '.join(f'`{rid}` {bj(ts)}' for rid, ts in rounds[:3])\n    if len(rounds) > 3:\n        src += f' 等 {len(rounds)} 轮'\n    n_located = canonical['global']['located']\n\n    L = []\n    L.append('# 全量插件清单（统一四档口径）')\n    L.append('')\n    L.append(f'> 数据源：radar 快照并集（{src}）⊕ GitHub 定位复核缓存（data/locate-cache.json）。')\n    L.append('> 呈现：分组列表（状态 · 名称 · ★星标 · 一句话说明），不使用大表格；〔📦〕= 整合包（根 dsh.bundle / workspaces 多子包）。')\n    L.append('')\n    L.append('## 统一度量衡')\n    L.append('')\n    L.append('**判定维度**（运行级四档；测试：dsh 容器 agent + Qwen3.6-35B · k8s 5 分片 · run_id 锚定轮次）：')\n    L.append('')\n    L.append(_runner_version_line(radar_ver))\n    L.append(f'- 全量判定 {sum(v_all.values())}（全体条目，含监测/未定位；README 磁贴为单快照即时口径，与本清单并集归并口径的差源见附录）：'\n             f'`[可用]`（{v_all.get(\"✅ 运行级可用\", 0)}）/ `[不兼容]`（{v_all.get(\"❌ 运行级不兼容\", 0)}）/ `[待定]`（{v_all.get(\"⚠️ 待定\", 0)}）')\n    L.append(f'- 已定位明细 {n_located}（本列表展示口径，另 {len(entries) - n_located} 条监测/未定位的判定暂不展示）：'\n             f'`[可用]`（{vc.get(\"✅ 运行级可用\", 0)}）/ `[不兼容]`（{vc.get(\"❌ 运行级不兼容\", 0)}）/ `[待定]`（{vc.get(\"⚠️ 待定\", 0)}）/ `[未测]`（{vc.get(\"⏳ 未测\", 0)}）')\n    L.append('')\n    L.append('**定位维度**（与判定正交；监测类不显示对错判定，原始结果保留于快照层）：')\n    L.append('')\n    L.append(f'- `[空仓监测]`（{n_empty}）— GitHub 复核无此仓库；待重现后恢复判定显示')\n    L.append(f'- `[歧义监测]`（{n_amb}）— 同名多仓无法锁定本体；锁定前不展示')\n    if n_unresolved:\n        L.append(f'- `[未定位]`（{n_unresolved}）— 新占位条目，待下一轮定位复核（scripts/resolve_placeholders.py）')\n    L.append(f'- 定位复核累计修复 {n_fix} 个占位 URL')\n    L.append('')\n    L.append('> 〔PR〕= 经已合并 PR 正式登记；收录 ≠ 兼容 ≠ 运行可用 ≠ 安全审计。')\n    L.append('')\n    L.append(f'## 汇总：{len(entries)} 条（已定位 {n_located} · 监测/未定位 {len(entries) - n_located}）· PR 登记 {len(pr_names)} 个')\n    L.append('')\n\n    dom_dir = ROOT / 'catalog' / 'all'\n    dom_dir.mkdir(parents=True, exist_ok=True)\n    for dom in DOMAIN_ORDER:\n        # 组内排序：星标降序；[不兼容] 整体沉组尾（组内仍按星标）——排除信息不占组头\n        group = sorted([e for e in entries if e.get('domain') == dom],\n                       key=lambda x: (x.get('verdict') == '❌ 运行级不兼容', -(x.get('star') or 0)))\n        if not group:\n            continue\n        dl = [f'# {dom}（{len(group)}）', '',\n              f'> 数据源与口径见 [PLUGINS-ALL.md](../../PLUGINS-ALL.md)（索引页）；磁贴图例同 README。', '']\n        for e in group:\n            name = e['name']\n            star = e.get('star')\n            star_part = f'★{star} ' if isinstance(star, int) else ''   # 星数未知留空不印 0（防污染排序，bot 日更补齐）\n            desc = (e.get('desc') or '—').strip()\n            if desc.startswith('http'):\n                desc = '—'\n            pr = ' 〔PR〕' if name in pr_names else ''\n            loc = e.get('locate')\n            if loc == 'empty_watch':\n                dl.append(f'- `[空仓监测]` **{name}** — GitHub 无此仓库，判定暂不展示{pr}')\n            elif loc == 'ambiguous_watch':\n                dl.append(f'- `[歧义监测]` **{name}** — 同名多仓，判定暂不展示{pr}')\n            elif loc == 'unresolved':\n                dl.append(f'- `[未定位]` **{name}** — 占位待复核，判定暂不展示{pr}')\n            else:\n                bundle_part = '〔📦〕' if e.get('bundle') else ''   # 整合包（dsh.bundle / workspaces 结构）\n                dl.append(f'- {MARK.get(e.get(\"verdict\"), \"⬜ `[未测]`\")} [{name}]({e[\"url\"]}) {star_part}— {desc}{pr}{bundle_part}')\n        dom_slug = dom.split(' ', 1)[-1]\n        dom_file = dom_dir / f'{dom_slug}.md'\n        dom_file.write_text('\\n'.join(dl).replace('](assets/', '](../../assets/') + '\\n', encoding='utf8')\n        g_ok = vc_local(entries, dom, '✅ 运行级可用')\n        g_bad = vc_local(entries, dom, '❌ 运行级不兼容')\n        g_inc = vc_local(entries, dom, '⚠️ 待定') + vc_local(entries, dom, '⏳ 未测')\n        L.append(f'- **{dom}**（{len(group)}）— 🟩 {g_ok} · 🟨 {g_bad} · ⬜ {g_inc} — [明细]({dom_file.relative_to(ROOT).as_posix().replace(chr(32), \"%20\")})')\n    L.append('')\n\n    L.append('## 附录')\n    L.append('')\n    L.append('- 判定与定位正交；监测类条目的原始判定保留于 data/snapshots/，定位成功后自动恢复展示。')\n    L.append('- 占位 URL 由发现管线 clone 库通道产生；定位复核：`python3 scripts/resolve_placeholders.py`（结果写 data/locate-cache.json，命中附实时 star）。')\n    L.append('- 合并主键以 GitHub 仓库身份为准（稳定编号与已核实改名/转移别名归一）：同一仓库的不同名称、插件与整合包记录合并为单条，类型作为标签保留；判定冲突降级 [待定] 待重测仲裁。')\n    L.append('- 口径对齐说明：README 磁贴/徽章与「运行级实测」行为单快照即时全量口径；本清单为多轮快照并集归并口径（同名多键合一、判定冲突降 [待定]、刷新随日更）。两者存在时滞与归并差，属设计特性；判定真相以 data/snapshots/ 逐轮快照为准。')\n    L.append('')\n\n    OUT.write_text('\\n'.join(L) + '\\n', encoding='utf8')\n    print(f'[render-all] {len(entries)} 条 → {OUT.name}（空仓 {n_empty} / 歧义 {n_amb} / 未定位 {n_unresolved}）')\n    return {'domains': canonical['domain_stats'], 'global': canonical['global']}\n\n\ndef main() -> int:\n    render()\n    return 0\n\n\nif __name__ == '__main__':\n    sys.exit(main())\n"
    },
